const String defaultSkinId = 'official';

/// Looks a skin up by id, falling back to the default (never throws).
AppSkin skinById(String id) {
  for (final AppSkin skin in appSkins) {
    if (skin.id == id) {
      return skin;
    }
  }
  return appSkins.first;
}
